const http = require('http');
const crypto = require('crypto');
const { promisify } = require('util');
const scryptAsync = promisify(crypto.scrypt);

// In-memory stores
const users = new Map();
const sessions = new Map();
const transferTokens = new Map(); // one-time-use tokens for fund transfers

// Crypto helpers
const SALT_LEN = 16;
const KEY_LEN = 64;
const MAX_BODY_SIZE = 1024 * 10; // 10 KB max request body

async function hashPassword(password) {
  const salt = crypto.randomBytes(SALT_LEN);
  const key = await scryptAsync(password, salt, KEY_LEN);
  return { salt: salt.toString('hex'), hash: key.toString('hex') };
}

async function verifyPassword(password, salt, storedHash) {
  const key = await scryptAsync(password, Buffer.from(salt, 'hex'), KEY_LEN);
  const a = Buffer.from(key.toString('hex'), 'hex');
  const b = Buffer.from(storedHash, 'hex');
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

// Initialize admin account
(async () => {
  const { salt, hash } = await hashPassword('admin_secure_pass_2024!');
  users.set('admin', { username: 'admin', passwordSalt: salt, passwordHash: hash, balance: 10000, role: 'admin' });
})();

// Middleware helpers
function authenticate(sessionToken) {
  if (!sessionToken) return null;
  const session = sessions.get(sessionToken);
  if (!session) return null;
  if (Date.now() > session.expiresAt) {
    sessions.delete(sessionToken);
    return null;
  }
  return users.get(session.username);
}

// Synchronous token validation - atomic in single-threaded Node.js
function validateAndConsumeTransferToken(tokenId) {
  const token = transferTokens.get(tokenId);
  if (!token) return null;
  if (token.used) return null;
  if (Date.now() > token.expiresAt) {
    transferTokens.delete(tokenId);
    return null;
  }
  // Atomically mark as used before returning - no yield point between check and mark
  token.used = true;
  return token;
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    let size = 0;
    let aborted = false;
    req.on('data', chunk => {
      if (aborted) return;
      size += chunk.length;
      if (size > MAX_BODY_SIZE) {
        aborted = true;
        reject(new Error('Payload too large'));
        req.destroy();
        return;
      }
      data += chunk;
    });
    req.on('end', () => {
      if (aborted) return;
      try { resolve(JSON.parse(data)); }
      catch (e) { reject(e); }
    });
    req.on('error', err => {
      if (aborted) return;
      aborted = true;
      reject(err);
    });
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const path = url.pathname;

  res.setHeader('Content-Type', 'application/json');

  try {
    // POST /register
    if (path === '/register' && req.method === 'POST') {
      const { username, password } = await parseBody(req);
      if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
        res.writeHead(400);
        return res.end(JSON.stringify({ error: 'Invalid input' }));
      }
      if (username.length > 32 || password.length > 128) {
        res.writeHead(400);
        return res.end(JSON.stringify({ error: 'Input too long' }));
      }
      if (users.has(username)) {
        res.writeHead(409);
        return res.end(JSON.stringify({ error: 'User exists' }));
      }
      const { salt, hash } = await hashPassword(password);
      users.set(username, { username, passwordSalt: salt, passwordHash: hash, balance: 1000, role: 'user' });
      res.writeHead(201);
      return res.end(JSON.stringify({ success: true }));
    }

    // POST /login
    if (path === '/login' && req.method === 'POST') {
      const { username, password } = await parseBody(req);
      if (!username || !password) {
        res.writeHead(400);
        return res.end(JSON.stringify({ error: 'Invalid input' }));
      }
      const user = users.get(username);
      if (!user) {
        res.writeHead(401);
        return res.end(JSON.stringify({ error: 'Invalid credentials' }));
      }
      const valid = await verifyPassword(password, user.passwordSalt, user.passwordHash);
      if (!valid) {
        res.writeHead(401);
        return res.end(JSON.stringify({ error: 'Invalid credentials' }));
      }
      const sessionToken = generateToken();
      sessions.set(sessionToken, { username, expiresAt: Date.now() + 3600000 });
      res.writeHead(200);
      return res.end(JSON.stringify({ sessionToken }));
    }

    // POST /create-transfer-token - creates a one-time-use token for transferring funds
    if (path === '/create-transfer-token' && req.method === 'POST') {
      const authHeader = req.headers['authorization'];
      const sessionToken = authHeader && authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;
      const user = authenticate(sessionToken);
      if (!user) {
        res.writeHead(401);
        return res.end(JSON.stringify({ error: 'Unauthorized' }));
      }
      const { amount, recipient } = await parseBody(req);
      if (!amount || !recipient || typeof amount !== 'number' || amount <= 0 || amount > user.balance) {
        res.writeHead(400);
        return res.end(JSON.stringify({ error: 'Invalid transfer parameters' }));
      }
      if (!users.has(recipient)) {
        res.writeHead(404);
        return res.end(JSON.stringify({ error: 'Recipient not found' }));
      }
      const tokenId = generateToken();
      transferTokens.set(tokenId, {
        id: tokenId,
        from: user.username,
        to: recipient,
        amount: amount,
        used: false,
        expiresAt: Date.now() + 300000, // 5 minutes
        createdAt: Date.now()
      });
      res.writeHead(201);
      return res.end(JSON.stringify({ tokenId, expiresAt: Date.now() + 300000 }));
    }

    // POST /execute-transfer - executes a transfer using a one-time token
    if (path === '/execute-transfer' && req.method === 'POST') {
      const authHeader = req.headers['authorization'];
      const sessionToken = authHeader && authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;
      const user = authenticate(sessionToken);
      if (!user) {
        res.writeHead(401);
        return res.end(JSON.stringify({ error: 'Unauthorized' }));
      }
      const { tokenId } = await parseBody(req);
      if (!tokenId || typeof tokenId !== 'string') {
        res.writeHead(400);
        return res.end(JSON.stringify({ error: 'Invalid token' }));
      }

      // Validate AND consume the transfer token atomically (synchronous - no yield point)
      const token = validateAndConsumeTransferToken(tokenId);
      if (!token) {
        res.writeHead(403);
        return res.end(JSON.stringify({ error: 'Invalid or expired transfer token' }));
      }

      // Verify the authenticated user is the token owner
      if (token.from !== user.username) {
        // Revert the consumption since this isn't the owner
        token.used = false;
        res.writeHead(403);
        return res.end(JSON.stringify({ error: 'Token does not belong to you' }));
      }

      // Check balance before transfer
      const sender = users.get(token.from);
      const receiver = users.get(token.to);
      if (!sender || !receiver) {
        token.used = false;
        res.writeHead(400);
        return res.end(JSON.stringify({ error: 'User not found' }));
      }
      if (sender.balance < token.amount) {
        token.used = false;
        res.writeHead(400);
        return res.end(JSON.stringify({ error: 'Insufficient funds' }));
      }

      // Execute the transfer
      sender.balance -= token.amount;
      receiver.balance += token.amount;

      res.writeHead(200);
      return res.end(JSON.stringify({
        success: true,
        newBalance: sender.balance,
        transferred: token.amount,
        to: token.to
      }));
    }

    // GET /balance
    if (path === '/balance' && req.method === 'GET') {
      const authHeader = req.headers['authorization'];
      const sessionToken = authHeader && authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;
      const user = authenticate(sessionToken);
      if (!user) {
        res.writeHead(401);
        return res.end(JSON.stringify({ error: 'Unauthorized' }));
      }
      res.writeHead(200);
      return res.end(JSON.stringify({ username: user.username, balance: user.balance }));
    }

    res.writeHead(404);
    res.end(JSON.stringify({ error: 'Not found' }));
  } catch (e) {
    res.writeHead(500);
    res.end(JSON.stringify({ error: 'Internal server error' }));
  }
});

server.listen(3000);
module.exports = server;
